∀ {ρ : { z // RH.IsCriticalStripZetaZero z }} {omega M Δ : ℝ} {omega_pos : 0 < omega} {sigma_ne : RH.stripSigma ρ ≠ 0}
  {gamma_pos : 0 < RH.stripGamma ρ} {M_eq : M = RH.gaborScore (RH.stripSigma ρ) (RH.stripGamma ρ) omega} {M_pos : 0 < M}
  {d_ne : RH.stripGamma ρ - omega ≠ 0} {Δ_pos : 0 < Δ} {Δ_le_two : Δ ≤ 2 * RH.stripGamma ρ * omega}
  {rest_le : ∀ τ ∉ RH.stripOrbitFinset ρ, RH.gaborScore (RH.stripSigma τ) (RH.stripGamma τ) omega ≤ M - Δ}
  {ρ_1 : { z // RH.IsCriticalStripZetaZero z }} {omega_1 M_1 Δ_1 : ℝ} {omega_pos_1 : 0 < omega_1}
  {sigma_ne_1 : RH.stripSigma ρ_1 ≠ 0} {gamma_pos_1 : 0 < RH.stripGamma ρ_1}
  {M_eq_1 : M_1 = RH.gaborScore (RH.stripSigma ρ_1) (RH.stripGamma ρ_1) omega_1} {M_pos_1 : 0 < M_1}
  {d_ne_1 : RH.stripGamma ρ_1 - omega_1 ≠ 0} {Δ_pos_1 : 0 < Δ_1} {Δ_le_two_1 : Δ_1 ≤ 2 * RH.stripGamma ρ_1 * omega_1}
  {rest_le_1 : ∀ τ ∉ RH.stripOrbitFinset ρ_1, RH.gaborScore (RH.stripSigma τ) (RH.stripGamma τ) omega_1 ≤ M_1 - Δ_1},
  { ρ := ρ, omega := omega, M := M, Δ := Δ, omega_pos := omega_pos, sigma_ne := sigma_ne, gamma_pos := gamma_pos,
        M_eq := M_eq, M_pos := M_pos, d_ne := d_ne, Δ_pos := Δ_pos, Δ_le_two := Δ_le_two, rest_le := rest_le } =
      { ρ := ρ_1, omega := omega_1, M := M_1, Δ := Δ_1, omega_pos := omega_pos_1, sigma_ne := sigma_ne_1,
        gamma_pos := gamma_pos_1, M_eq := M_eq_1, M_pos := M_pos_1, d_ne := d_ne_1, Δ_pos := Δ_pos_1,
        Δ_le_two := Δ_le_two_1, rest_le := rest_le_1 } →
    ρ = ρ_1 ∧ omega = omega_1 ∧ M = M_1 ∧ Δ = Δ_1

