  {u : ℕ → ℝ} {B : ℝ} {S_1 : ℕ} {nodes_1 combWeight_1 archWeight_1 : Fin S_1 → ℝ}
  {comb_nonneg_1 : ∀ (j : Fin S_1), 0 ≤ combWeight_1 j} {arch_nonneg_1 : ∀ (j : Fin S_1), 0 ≤ archWeight_1 j}
  {lo_1 hi_1 : ℝ} {window_rule_1 : ∀ (j : Fin S_1), lo_1 ≤ nodes_1 j ∧ nodes_1 j ≤ hi_1} {u_1 : ℕ → ℝ} {B_1 : ℝ},
  { S := S, nodes := nodes, combWeight := combWeight, archWeight := archWeight, comb_nonneg := comb_nonneg,
        arch_nonneg := arch_nonneg, lo := lo, hi := hi, window_rule := window_rule, u := u, B := B } =
