  AnalyticAt ℂ (Function.update (RH.logDerivHatRemainder F σ₁ σ₂ T) s (RH.logDerivHatRemainderFillAtZero hF hs)) s

∀ {h : ℝ → ℝ} {K : NNReal} {a R : ℝ},
  LipschitzWith K h →
    (∀ (t : ℝ), t < a ∨ a + R < t → h t = 0) →
      0 ≤ R →
        ∀ (m d : ℕ),
          have D := RH.meshWidth m;
          have n := (RH.dyadicSampleGrid h a R m).steps;
          have φ := fun t => h t * h (t + ↑d * D);
          |(D * ∑ i, if hi : ↑i + d < n then φ (a + ↑↑i * D) else 0) - D * ∑ i, φ (a + ↑↑i * D)| ≤ (↑K * R) ^ 2 * D

∀ {h : ℝ → ℝ} {K : NNReal} {a R : ℝ},
  LipschitzWith K h →
    (∀ (t : ℝ), t < a ∨ a + R < t → h t = 0) →
      0 ≤ R →
        ∀ (m d : ℕ),
          have D := RH.meshWidth m;
          have n := (RH.dyadicSampleGrid h a R m).steps;
          have φ := fun t => h t * h (t + ↑d * D);
          |D * ∑ k ∈ Finset.range n, φ (a + ↑k * D) - intervalIntegral φ a (a + ↑n * D) MeasureTheory.volume| ≤
            2 * (↑K * R) ^ 2 * D

∀ (h : ℝ → ℝ) (a : ℝ) (m d n : ℕ),
  have D := RH.meshWidth m;
  have φ := fun t => h t * h (t + ↑d * D);
  ∑ i, φ (a + ↑↑i * D) = ∑ k ∈ Finset.range n, φ (a + ↑k * D)

∀ {h : ℝ → ℝ} {K : NNReal} {a R : ℝ},
  LipschitzWith K h →
    (∀ (t : ℝ), t < a ∨ a + R < t → h t = 0) →
      0 ≤ R →
        ∀ (m d : ℕ),
          have D := RH.meshWidth m;
          have n := (RH.dyadicSampleGrid h a R m).steps;
          have φ := fun t => h t * h (t + ↑d * D);
          |intervalIntegral φ a (a + ↑n * D) MeasureTheory.volume - intervalIntegral φ a (a + R) MeasureTheory.volume| ≤
            (↑K * R) ^ 2 * D

∀ (F : RH.FullWeilTest) (u : ℝ),
  RH.fullWeilArchUIntegrand F u =
    if u = 0 then 0 else RH.weilArchUWeight u * (Real.exp (-(3 / 2) * u) * F.toFun 0 - F.toFun u)

∀ (F : RH.GaborWeilTest) (s : ℂ),
  RH.gaborHat F s =
    if F.coeffs = { c0 := 1, c2 := 0, c4 := 0 } then RH.pureGaborHatDelta F.a F.omega (s - 1 / 2)
    else RH.gaborLaplace F (s - 1 / 2) * RH.gaborLaplace F (-(s - 1 / 2))

∀ (sigma gamma : ℝ) (hs0 : 0 < sigma) (hs1 : sigma < 1 / 2) (hg : 0 < gamma),
  RH.gaborSingletonConfig sigma gamma hs0 hs1 hg =
    { pts := {(sigma, gamma)}, mult := fun x => 1, mult_pos := ⋯, sigma_off := ⋯, gamma_pos := ⋯ }

∀ (T : ℝ),
  RH.gaborZerosUpTo (T + 1) \ RH.gaborZerosUpTo T ⊆
    {z ∈ RH.riemannZetaZerosOnClosedRect 0 1 (T + 1) | T ≤ z.im ∧ z.im ≤ T + 1}

∀ {n : Type u_1} {k : Type u_2} [inst : Fintype n] [inst_1 : Fintype k] [inst_2 : DecidableEq n]
  [inst_3 : DecidableEq k] (A : Matrix n n ℝ) (U : Matrix n k ℝ) (J : Matrix k k ℝ),
  A.IsHermitian →
    J.IsHermitian →
      ∀ [Invertible A] [Invertible J],
        have Φ := J⁻¹ + U.transpose * A⁻¹ * U;
        have H := Matrix.fromBlocks A U U.transpose (-J⁻¹);
        have M := A + U * J * U.transpose;
        sigNeg H.toQuadraticMap' = sigNeg A.toQuadraticMap' + sigNeg (-Φ).toQuadraticMap' ∧
          sigNeg H.toQuadraticMap' = sigNeg M.toQuadraticMap' + sigNeg (-J⁻¹).toQuadraticMap'

∀ {p : ℕ} (w : RH.VonMangoldtWindow) (Q : Matrix (Fin p) (Fin p) ℝ) (σ : ℝ),
  Q.transpose * w.combHankel p * Q = 1 →
    σ * σ * ↑w.B = 1 →
      have E := Q.transpose * w.archHankel p * Q;
      have vv := -(σ • Q.transpose.mulVec (w.borderVec p));
      have S := Matrix.fromBlocks Q 0 0 (RH.borderCorner σ);
      S.transpose * w.A p * S = 1 - RH.borderedGram E vv 0

∀ {p : ℕ} (w : RH.PrimeWindow) (Q : Matrix (Fin p) (Fin p) ℝ) (σ : ℝ),
  Q.transpose * w.combHankel p * Q = 1 →
    σ * σ * w.B = 1 →
      have E := Q.transpose * w.archHankel p * Q;
      have vv := -(σ • Q.transpose.mulVec (w.borderVec p));
      have S := Matrix.fromBlocks Q 0 0 (RH.borderCorner σ);
      S.transpose * w.A p * S = 1 - RH.borderedGram E vv 0

∀ (a m i : ℕ),
  RH.productionArchLag a m i =
    if i = 0 then RH.productionArchLagNear (RH.productionArchDelta a m) (↑i * RH.productionArchDelta a m)
    else RH.productionArchLagFar (RH.productionArchDelta a m) (↑i * RH.productionArchDelta a m)

RH.stripFEEquiv =
  { toFun := fun ρ => ⟨1 - ↑ρ, ⋯⟩, invFun := fun ρ => ⟨1 - ↑ρ, ⋯⟩, left_inv := RH.stripFEEquiv._proof_3,
    right_inv := RH.stripFEEquiv._proof_3 }

RH.stripStarEquiv =
  { toFun := fun ρ => ⟨star ↑ρ, ⋯⟩, invFun := fun ρ => ⟨star ↑ρ, ⋯⟩, left_inv := RH.stripStarEquiv._proof_3,
    right_inv := RH.stripStarEquiv._proof_3 }

∀ (f : RH.GridElement) (u : ℝ),
  RH.weilArchUIntegrand f u =
    if u = 0 then 0 else RH.weilArchUWeight u * (Real.exp (-(3 / 2) * u) * f.toFun 0 - f.toFun u)

∀ {κ : ℕ → Type u_1} {A : (m : ℕ) → Matrix (κ m) (κ m) ℝ} {idx : ℕ → ℕ} {mono : StrictMono idx}
  {psd : ∀ (j : ℕ), (A (idx j)).PosSemidef} {idx_1 : ℕ → ℕ} {mono_1 : StrictMono idx_1}
  {psd_1 : ∀ (j : ℕ), (A (idx_1 j)).PosSemidef},
  { idx := idx, mono := mono, psd := psd } = { idx := idx_1, mono := mono_1, psd := psd_1 } → idx = idx_1

∀ {κ : ℕ → Type u_1} [inst : (m : ℕ) → Fintype (κ m)] {V : Type u_2} {A : (m : ℕ) → Matrix (κ m) (κ m) ℝ}
  (sample : (m : ℕ) → V → κ m → ℝ) {m : ℕ},
  (A m).PosSemidef → ∀ (v : V), 0 ≤ TfptCarrier.CofinalWeil.ladderForm A sample m v

∀ {κ : ℕ → Type u_2} {inst : (m : ℕ) → Fintype (κ m)} {S C : (m : ℕ) → Matrix (κ m) (κ m) ℝ} {x : (m : ℕ) → κ m → ℝ}
  {S_1 C_1 : (m : ℕ) → Matrix (κ m) (κ m) ℝ} {x_1 : (m : ℕ) → κ m → ℝ},
  { S := S, C := C, x := x } = { S := S_1, C := C_1, x := x_1 } → S = S_1 ∧ C = C_1 ∧ x = x_1

∀ {κ : ℕ → Type u_2} {inst : (m : ℕ) → Fintype (κ m)} {inst_1 : (m : ℕ) → DecidableEq (κ m)}
  {φ : (m : ℕ) → Matrix (κ (m + 1)) (κ (m + 1)) ℝ → Matrix (κ m) (κ m) ℝ} {e : (m : ℕ) → Matrix (κ m) (κ m) ℝ}
  {proj : ∀ (m : ℕ), TfptCarrier.SectorPositiveDescent.IsOrthogonalProjection (e m)}
  {pos : ∀ (m : ℕ) (a : Matrix (κ (m + 1)) (κ (m + 1)) ℝ), a.PosSemidef → (φ m a).PosSemidef}
  {unital : ∀ (m : ℕ), φ m 1 = 1}
  {compat :
    ∀ (m : ℕ) (a : Matrix (κ (m + 1)) (κ (m + 1)) ℝ),
      φ m (TfptCarrier.SectorPositiveDescent.corner (e (m + 1)) a) =
        TfptCarrier.SectorPositiveDescent.corner (e m) (φ m a)}
  {φ_1 : (m : ℕ) → Matrix (κ (m + 1)) (κ (m + 1)) ℝ → Matrix (κ m) (κ m) ℝ} {e_1 : (m : ℕ) → Matrix (κ m) (κ m) ℝ}
  {proj_1 : ∀ (m : ℕ), TfptCarrier.SectorPositiveDescent.IsOrthogonalProjection (e_1 m)}
  {pos_1 : ∀ (m : ℕ) (a : Matrix (κ (m + 1)) (κ (m + 1)) ℝ), a.PosSemidef → (φ_1 m a).PosSemidef}
  {unital_1 : ∀ (m : ℕ), φ_1 m 1 = 1}
  {compat_1 :
    ∀ (m : ℕ) (a : Matrix (κ (m + 1)) (κ (m + 1)) ℝ),
      φ_1 m (TfptCarrier.SectorPositiveDescent.corner (e_1 (m + 1)) a) =
        TfptCarrier.SectorPositiveDescent.corner (e_1 m) (φ_1 m a)},
  { φ := φ, e := e, proj := proj, pos := pos, unital := unital, compat := compat } =
      { φ := φ_1, e := e_1, proj := proj_1, pos := pos_1, unital := unital_1, compat := compat_1 } →
    φ = φ_1 ∧ e = e_1
